'use client';

import { useParams } from 'next/navigation';

export default function MenuDetail() {
  const { menuCode } = useParams(); // /menu/? 동적인 값을 읽어옴

  return (
    <>
      <h1>메뉴 상세 페이지</h1>
      {/* <p>주소에서 받은 menuCode: {menuCode}</p> */}
      {/*menuCode라는 이름은 폴더 이름 [menuCode]에서 가져옴*/}
    </>
  );
}
